// Exact cached-zero analyzer for Q4279.
// Reads disjoint, complete Z_p shards; reconstructs raw q6 candidates with the
// regression-validated inverse maps; applies raw minus-first; tests t in Z_q;
// and emits per-q, dyadic, near-miss, heuristic, and K-multiplicity ledgers.

#define main q4279_embedded_scan_main
#include "q4279_scan.cpp"
#undef main

namespace {
struct AOpt {u32 qlo=1000000,qhi=19999999,block=250000;std::string records,counts,out="analysis";};
AOpt aopts(int ac,char**av){AOpt o;for(int i=1;i<ac;++i){std::string a=av[i];auto need=[&](){if(++i>=ac)throw std::runtime_error("missing value");return std::string(av[i]);};if(a=="--qmin-exclusive")o.qlo=std::stoul(need());else if(a=="--qmax")o.qhi=std::stoul(need());else if(a=="--zero-records")o.records=need();else if(a=="--zero-counts")o.counts=need();else if(a=="--block-width")o.block=std::stoul(need());else if(a=="--out")o.out=need();else if(a=="-h"||a=="--help"){std::cout<<"q4279_cached_analyze --qmin-exclusive N --qmax N --zero-records FILE --zero-counts FILE [--block-width N] [--out DIR]\n";std::exit(0);}else throw std::runtime_error("unknown option "+a);}if(o.qhi<=o.qlo||o.records.empty()||o.counts.empty())throw std::runtime_error("bad analyzer options");return o;}
std::vector<std::string> split(const std::string&s){std::vector<std::string>v;std::string x;std::istringstream in(s);while(std::getline(in,x,','))v.push_back(x);return v;}
struct Fit{u64 n=0;long double sx=0,sy=0,sxx=0,sxy=0,syy=0;void add(long double x,long double y){++n;sx+=x;sy+=y;sxx+=x*x;sxy+=x*y;syy+=y*y;}std::tuple<double,double,double> result()const{if(n<2)return{NAN,NAN,NAN};long double den=n*sxx-sx*sx;if(den==0)return{NAN,NAN,NAN};long double b=(n*sxy-sx*sy)/den,a=(sy-b*sx)/n;long double sst=syy-sy*sy/n,sse=syy+a*a*n+b*b*sxx+2*a*b*sx-2*a*sy-2*b*sxy;return{double(a),double(b),double(sst>0?1-sse/sst:1)};}};
struct DStats{u32 lo=0,hi=0;u64 primes=0,sumz=0,suma=0,qa=0,occ=0,hits=0,candz=0,maxa=0,maxz=0,maxk=0;long double heur=0;std::vector<i64>cyc;std::vector<double>norm,scaled;};
struct NRow{u32 q,t,p,zc,A;char s;i64 zero,lin,cyc;bool hit;};
}

int main(int ac,char**av){try{AOpt o=aopts(ac,av);fs::create_directories(o.out);auto t0=std::chrono::steady_clock::now();Check ck=validate();u32 qstart=o.qlo+1,pmin=u32(6ULL*qstart/7+1);auto pr=primes_to(o.qhi);std::vector<std::int32_t>ix(o.qhi+1,-1);for(std::size_t i=0;i<pr.size();++i)ix[pr[i]]=i;std::vector<std::vector<u32>>Z(pr.size());std::vector<std::int32_t>expected(pr.size(),-1);std::vector<std::uint8_t>seen(pr.size(),0);std::string line;
 {std::ifstream f(o.counts);if(!f)throw std::runtime_error("open zero counts");while(std::getline(f,line)){if(line.empty()||line[0]=='p')continue;auto v=split(line);if(v.size()!=2)throw std::runtime_error("bad zero count row");u32 p=std::stoul(v[0]);if(p>o.qhi||ix[p]<0)throw std::runtime_error("count row nonprime/out of range");std::size_t i=ix[p];if(seen[i])throw std::runtime_error("duplicate prime count row");seen[i]=1;expected[i]=std::stoi(v[1]);}}
 {std::ifstream f(o.records);if(!f)throw std::runtime_error("open zero records");while(std::getline(f,line)){if(line.empty()||line[0]=='p')continue;auto v=split(line);if(v.size()!=2)throw std::runtime_error("bad zero record row");u32 p=std::stoul(v[0]),r=std::stoul(v[1]);if(p>o.qhi||ix[p]<0||r>=p)throw std::runtime_error("bad zero record value");Z[ix[p]].push_back(r);}}
 std::size_t first=std::lower_bound(pr.begin(),pr.end(),pmin)-pr.begin();u64 covered=0,zrecords=0,refl=0,rf=0,cons=0,cf=0;for(std::size_t i=first;i<pr.size();++i){if(!seen[i])throw std::runtime_error("missing prime zero-count row");++covered;auto&z=Z[i];std::sort(z.begin(),z.end());if(std::adjacent_find(z.begin(),z.end())!=z.end())throw std::runtime_error("duplicate zero record");if(expected[i]!=i64(z.size()))throw std::runtime_error("zero count mismatch");zrecords+=z.size();for(u32 r:z){++refl;if(!has(z,pr[i]-1-r))++rf;}for(std::size_t j=1;j<z.size();++j){++cons;if(z[j]==z[j-1]+1)++cf;}}if(rf||cf)throw std::runtime_error("cached reflection/consecutive failure");
 Proj ps;auto raw=project(pr,ix,Z,pmin,o.qlo,o.qhi,ps);auto oc=merge(raw);u64 rawp=0,rawm=0,over=0,asp=0,asmn=0;for(auto&x:oc){rawp+=x.rp;rawm+=x.rm;over+=x.rp&&x.rm;if(x.sign()=='+')++asp;else++asmn;}
 std::ofstream co(fs::path(o.out)/"candidate_occurrences.csv");co<<"sign,q,t,p,r,a_plus,a_minus,raw_plus,raw_minus,Zq,selected,nearest_zero,linear,cyclic,scaled_A\n";std::ofstream qf(fs::path(o.out)/"q_stats.csv");qf<<"q,Z,A,Ap,Am,rawO,O,Kpre,Ksel,actualP,actualM,dlin,dcyc,scaled_A,heur\n";std::ofstream mfib(fs::path(o.out)/"multi_fibres.csv");mfib<<"q,t,sign,K,p_list\n";std::size_t nb=(o.qhi-o.qlo+o.block-1)/o.block;std::vector<Block>B(nb);for(std::size_t b=0;b<nb;++b){B[b].lo=o.qlo+b*o.block;B[b].hi=std::min<u32>(o.qhi,B[b].lo+o.block);}std::array<std::pair<u32,u32>,5>dr={{{1000000,2000000},{2000000,4000000},{4000000,8000000},{8000000,16000000},{16000000,19999999}}};std::array<DStats,5>D;for(int i=0;i<5;++i){D[i].lo=dr[i].first;D[i].hi=dr[i].second;}auto didx=[&](u32 q){for(int i=0;i<5;++i)if(q>D[i].lo&&q<=D[i].hi)return i;return-1;};std::vector<NRow>near;std::vector<Occ>wit;std::map<u64,u64>Adist,Zdist;std::size_t cp=0;u64 up=0,qA=0,sumA=0,maxK=0,maxKs=0,maxA=0,maxAq=0,actualP=0,actualM=0;long double H=0;Fit fnorm,fscaled;auto qbegin=std::lower_bound(pr.begin(),pr.end(),qstart);
 for(auto it=qbegin;it!=pr.end();++it){u32 q=*it;std::size_t qi=it-pr.begin();++up;while(cp<oc.size()&&oc[cp].q<q)++cp;std::size_t b0=cp;while(cp<oc.size()&&oc[cp].q==q)++cp;std::size_t b1=cp;const auto&zq=Z[qi];std::vector<u32>au,ap,am;u64 rawO=0,actp=0,actm=0,Kpre=0,Ksel=0;i64 dl=-1,dc=-1;std::map<std::pair<u32,char>,std::vector<const Occ*>>fib;for(std::size_t k=b0;k<b1;++k){auto&x=oc[k];fib[{x.t,x.sign()}].push_back(&x);au.push_back(x.t);(x.sign()=='+'?ap:am).push_back(x.t);rawO+=x.raw_count();}auto un=[](auto&v){std::sort(v.begin(),v.end());v.erase(std::unique(v.begin(),v.end()),v.end());};un(au);un(ap);un(am);for(auto&kv:fib){u64 kp=kv.second.size(),ks=0;for(auto*x:kv.second)if(has(zq,x->t))++ks;Kpre=std::max(Kpre,kp);Ksel=std::max(Ksel,ks);if(kp>=2){mfib<<q<<','<<kv.first.first<<','<<kv.first.second<<','<<kp<<',';for(std::size_t j=0;j<kv.second.size();++j){if(j)mfib<<';';mfib<<kv.second[j]->p;}mfib<<'\n';}}
 for(std::size_t k=b0;k<b1;++k){auto&x=oc[k];bool sel=has(zq,x.t);Near n=nearest(q,x.t,zq);if(sel){wit.push_back(x);if(x.sign()=='+')++actp;else++actm;}if(n.lin>=0&&(dl<0||n.lin<dl))dl=n.lin;if(n.cyc>=0&&(dc<0||n.cyc<dc))dc=n.cyc;double sc=(n.cyc>=0&&!zq.empty()&&!au.empty())?2.0*au.size()*zq.size()*n.cyc/q:-1;near.push_back({q,x.t,x.p,u32(zq.size()),u32(au.size()),x.sign(),n.zero,n.lin,n.cyc,sel});co<<x.sign()<<','<<q<<','<<x.t<<','<<x.p<<','<<x.r<<','<<x.ap<<','<<x.am<<','<<x.rp<<','<<x.rm<<','<<zq.size()<<','<<sel<<','<<n.zero<<','<<n.lin<<','<<n.cyc<<','<<sc<<'\n';}
 if(!au.empty())++qA;sumA+=au.size();if(au.size()>maxA){maxA=au.size();maxAq=q;}maxK=std::max(maxK,Kpre);maxKs=std::max(maxKs,Ksel);actualP+=actp;actualM+=actm;long double heur=static_cast<long double>(au.size())*zq.size()/q;H+=heur;double scaled=(dc>=0&&!zq.empty()&&!au.empty())?2.0*au.size()*zq.size()*dc/q:-1;if(dc>=0){fnorm.add(std::log((long double)q),std::log((long double)dc/q));if(scaled>0)fscaled.add(std::log((long double)q),std::log((long double)scaled));}qf<<std::setprecision(17)<<q<<','<<zq.size()<<','<<au.size()<<','<<ap.size()<<','<<am.size()<<','<<rawO<<','<<(b1-b0)<<','<<Kpre<<','<<Ksel<<','<<actp<<','<<actm<<','<<dl<<','<<dc<<','<<scaled<<','<<double(heur)<<'\n';++Adist[au.size()];++Zdist[zq.size()];Block&bb=B[std::min<std::size_t>(nb-1,(q-qstart)/o.block)];++bb.primes;bb.sumz+=zq.size();bb.suma+=au.size();bb.occ+=b1-b0;bb.hits+=actp+actm;bb.maxz=std::max<u64>(bb.maxz,zq.size());bb.maxa=std::max<u64>(bb.maxa,au.size());bb.maxk=std::max(bb.maxk,Kpre);if(!zq.empty())++bb.qz;if(!au.empty())++bb.qa;bb.heur+=heur;if(dl>=0){bb.lin.push_back(dl);bb.norm.push_back(double(dl)/q);}int di=didx(q);if(di>=0){auto&d=D[di];++d.primes;d.sumz+=zq.size();d.suma+=au.size();d.occ+=b1-b0;d.hits+=actp+actm;d.maxz=std::max<u64>(d.maxz,zq.size());d.maxa=std::max<u64>(d.maxa,au.size());d.maxk=std::max(d.maxk,Kpre);if(!au.empty())++d.qa;d.heur+=heur;if(!au.empty()&&!zq.empty())++d.candz;if(dc>=0){d.cyc.push_back(dc);d.norm.push_back(double(dc)/q);if(scaled>0)d.scaled.push_back(scaled);}}}
 std::sort(near.begin(),near.end(),[](const auto&a,const auto&b){i64 x=a.cyc<0?std::numeric_limits<i64>::max():a.cyc,y=b.cyc<0?std::numeric_limits<i64>::max():b.cyc;return std::make_tuple(x,a.q,a.t,a.p,a.s)<std::make_tuple(y,b.q,b.t,b.p,b.s);});std::ofstream nf(fs::path(o.out)/"near_misses.csv");nf<<"rank,cyclic,linear,nearest_zero,sign,q,t,p,Z,A,selected,scaled_A\n";for(std::size_t i=0;i<near.size();++i){auto&x=near[i];double sc=(x.cyc>=0&&x.zc&&x.A)?2.0*x.A*x.zc*x.cyc/x.q:-1;nf<<i+1<<','<<x.cyc<<','<<x.lin<<','<<x.zero<<','<<x.s<<','<<x.q<<','<<x.t<<','<<x.p<<','<<x.zc<<','<<x.A<<','<<x.hit<<','<<sc<<'\n';}
 std::ofstream bf(fs::path(o.out)/"block_stats.csv");bf<<"lo_exclusive,hi_inclusive,primes,qZ,qA,sumZ,sumA,occ,hits,maxZ,maxA,maxK,meanZ,meanA,meanAlog,heur_sum,median_linear,median_norm\n";bf<<std::setprecision(17);for(auto&b:B)if(b.primes){long double mid=(b.lo+b.hi)/2.0L,L=std::log(mid);bf<<b.lo<<','<<b.hi<<','<<b.primes<<','<<b.qz<<','<<b.qa<<','<<b.sumz<<','<<b.suma<<','<<b.occ<<','<<b.hits<<','<<b.maxz<<','<<b.maxa<<','<<b.maxk<<','<<double((long double)b.sumz/b.primes)<<','<<double((long double)b.suma/b.primes)<<','<<double((long double)b.suma/b.primes*L)<<','<<double(b.heur)<<','<<med(b.lin)<<','<<med(b.norm)<<'\n';}
 std::ofstream df(fs::path(o.out)/"dyadic_stats.csv");df<<"lo_exclusive,hi_inclusive,log_span,primes,sumZ,sumA,qA,candidate_with_Z,occ,hits,maxZ,maxA,maxK,meanZ,meanA,meanAlog,heur_sum,heur_per_log,heur_per_log_times_log,heur_per_log_times_log2,min_cyclic,median_cyclic,median_normalized,median_scaled_A\n";df<<std::setprecision(17);for(auto&d:D)if(d.primes){long double mid=std::sqrt((long double)d.lo*d.hi),L=std::log(mid),span=std::log((long double)d.hi/d.lo),hp=d.heur/span;i64 mn=d.cyc.empty()?-1:*std::min_element(d.cyc.begin(),d.cyc.end());df<<d.lo<<','<<d.hi<<','<<double(span)<<','<<d.primes<<','<<d.sumz<<','<<d.suma<<','<<d.qa<<','<<d.candz<<','<<d.occ<<','<<d.hits<<','<<d.maxz<<','<<d.maxa<<','<<d.maxk<<','<<double((long double)d.sumz/d.primes)<<','<<double((long double)d.suma/d.primes)<<','<<double((long double)d.suma/d.primes*L)<<','<<double(d.heur)<<','<<double(hp)<<','<<double(hp*L)<<','<<double(hp*L*L)<<','<<mn<<','<<med(d.cyc)<<','<<med(d.norm)<<','<<med(d.scaled)<<'\n';}
 std::ofstream dist(fs::path(o.out)/"distributions.csv");dist<<"kind,value,prime_count\n";for(auto[k,v]:Adist)dist<<"A,"<<k<<','<<v<<'\n';for(auto[k,v]:Zdist)dist<<"Z,"<<k<<','<<v<<'\n';std::ofstream wf(fs::path(o.out)/"witnesses.txt");if(wit.empty())wf<<"NO RAW MINUS-FIRST SELECTED q6 LEAF FOUND FOR "<<o.qlo<<" < q <= "<<o.qhi<<".\nFINITE EXHAUSTED RANGE, NOT A THEOREM.\n";else for(auto&x:wit)wf<<x.sign()<<" q="<<x.q<<" t="<<x.t<<" p="<<x.p<<" r="<<x.r<<" ap="<<x.ap<<" am="<<x.am<<'\n';wf<<"MAX_PREMARK_K="<<maxK<<"\nMAX_SELECTED_K="<<maxKs<<'\n';
 auto [na,nbeta,nr2]=fnorm.result();auto [sa,sbeta,sr2]=fscaled.result();double total=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count();std::ofstream m(fs::path(o.out)/"manifest.json");m<<std::setprecision(17)<<"{\n  \"qmin_exclusive\": "<<o.qlo<<",\n  \"qmax\": "<<o.qhi<<",\n  \"pmin_complete\": "<<pmin<<",\n  \"covered_lower_primes\": "<<covered<<",\n  \"cached_zero_records\": "<<zrecords<<",\n  \"upper_primes\": "<<up<<",\n  \"raw_plus\": "<<rawp<<",\n  \"raw_minus\": "<<rawm<<",\n  \"raw_overlap\": "<<over<<",\n  \"assigned_plus\": "<<asp<<",\n  \"assigned_minus\": "<<asmn<<",\n  \"candidate_states\": "<<sumA<<",\n  \"q_with_candidates\": "<<qA<<",\n  \"actual_plus\": "<<actualP<<",\n  \"actual_minus\": "<<actualM<<",\n  \"actual_leaf_occurrences\": "<<wit.size()<<",\n  \"max_premark_K\": "<<maxK<<",\n  \"max_selected_K\": "<<maxKs<<",\n  \"max_Aq\": "<<maxA<<",\n  \"max_Aq_prime\": "<<maxAq<<",\n  \"heuristic_sum_AZ_over_q\": "<<double(H)<<",\n  \"heuristic_poisson_no_hit\": "<<std::exp(-double(H))<<",\n  \"normalized_margin_loglog_fit\": {\"n\": "<<fnorm.n<<", \"intercept\": "<<na<<", \"slope\": "<<nbeta<<", \"r2\": "<<nr2<<"},\n  \"scaled_A_margin_loglog_fit\": {\"n\": "<<fscaled.n<<", \"intercept\": "<<sa<<", \"slope\": "<<sbeta<<", \"r2\": "<<sr2<<"},\n  \"projection\": {\"eligible_primes\": "<<ps.eligible<<", \"ordered_pairs\": "<<ps.pairs<<", \"parity_pruned\": "<<ps.parity<<", \"gap_pruned\": "<<ps.gap<<", \"plus_integral\": "<<ps.pint<<", \"plus_prime\": "<<ps.pprime<<", \"minus_integral\": "<<ps.mint<<", \"minus_prime\": "<<ps.mprime<<"},\n  \"checks\": {\"release_selected_states_le_5000\": "<<ck.states<<", \"release_selected_leaves_le_5000\": "<<ck.leaves<<", \"release_candidate_mismatch\": "<<ck.cmis<<", \"coverage_complete\": true, \"reflection_checks\": "<<refl<<", \"reflection_failures\": "<<rf<<", \"consecutive_checks\": "<<cons<<", \"consecutive_failures\": "<<cf<<"},\n  \"analysis_seconds\": "<<total<<"\n}\n";std::ofstream s(fs::path(o.out)/"summary.md");s<<"# Q4279 cached exact analysis\n\n- Range: `"<<o.qlo<<" < q <= "<<o.qhi<<"`.\n- Complete lower-prime start: `"<<pmin<<"`.\n- Candidate states: `"<<sumA<<"`.\n- Actual leaf occurrences: `"<<wit.size()<<"`.\n- Max pre-mark K: `"<<maxK<<"`.\n- Heuristic sum: `"<<double(H)<<"`.\n- This is a finite computation, not a theorem.\n";std::cout<<"Q4279_CACHED_ANALYSIS_COMPLETE qmax="<<o.qhi<<" candidates="<<sumA<<" leaves="<<wit.size()<<" maxK="<<maxK<<" heuristic="<<double(H)<<" seconds="<<total<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"Q4279_CACHED_ANALYZE_FATAL "<<e.what()<<'\n';return 2;}}
